-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Zentralelemente > Netzteile
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzteil unabhängig von der Leistungsanforderung der Komponenten ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Leistung muss Bedarf decken"}, {"text": "Ja", "correct": false, "because": "Unterdimensionierung führt zu Ausfällen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Netzteile immer mit modularen Kabeln ausgestattet sein?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht-modular ist ebenfalls funktional"}, {"text": "Ja", "correct": false, "because": "Modularität ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Effizienz eines Netzteils für den Stromverbrauch irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Effizienz reduziert Verlust und Kosten"}, {"text": "Ja", "correct": false, "because": "Effizienz beeinflusst Verbrauch"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Netzteile ohne Berücksichtigung des Formfaktors ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Muss zum Gehäuse passen"}, {"text": "Ja", "correct": false, "because": "Formfaktor ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Netzteil mit höherer Wattzahl immer besser für jedes System?', 2, '[{"text": "Nein", "correct": true, "because": "Überdimensionierung kann ineffizient sein"}, {"text": "Ja", "correct": false, "because": "Passgenauigkeit ist wichtiger"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Auswahl eines Netzteils am kritischsten?', 3, '[{"text": "Leistungsbedarf der Komponenten", "correct": true, "because": "Bestimmt Wattzahl"}, {"text": "Farbe des Netzteils", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Marke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zertifizierung gibt Auskunft über die Effizienz eines Netzteils?', 2, '[{"text": "80 PLUS", "correct": true, "because": "Standard für Effizienz"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement"}, {"text": "IP68", "correct": false, "because": "Schutzart"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Anschluss versorgt das Mainboard primär mit Strom?', 2, '[{"text": "24-Pin-ATX", "correct": true, "because": "Hauptstromanschluss"}, {"text": "SATA-Power", "correct": false, "because": "Für Laufwerke"}, {"text": "PCIe-Stecker", "correct": false, "because": "Für Grafikkarten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Wattzahl ist für ein System mit High-End-Grafikkarte und Prozessor typisch?', 3, '[{"text": "600-800 W", "correct": true, "because": "Deckt hohen Bedarf ab"}, {"text": "300-400 W", "correct": false, "because": "Zu niedrig"}, {"text": "1000 W", "correct": false, "because": "Oft überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was erhöht die Lebensdauer eines Netzteils?', 2, '[{"text": "Hohe Effizienz", "correct": true, "because": "Weniger Wärme und Verschleiß"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Irrelevant"}, {"text": "Kleine Größe", "correct": false, "because": "Nicht entscheidend"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl eines Netzteils?', 4, '[{"text": "Wattzahl", "correct": true, "because": "Muss Komponenten versorgen"}, {"text": "Effizienz", "correct": true, "because": "Reduziert Verbrauch"}, {"text": "Formfaktor", "correct": true, "because": "Passt zum Gehäuse"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anschlüsse kann ein Netzteil bereitstellen?', 3, '[{"text": "24-Pin-ATX", "correct": true, "because": "Für Mainboard"}, {"text": "PCIe-Stecker", "correct": true, "because": "Für Grafikkarten"}, {"text": "SATA-Power", "correct": true, "because": "Für Laufwerke"}, {"text": "USB-C", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei einem ungeeigneten Netzteil auftreten?', 3, '[{"text": "Systeminstabilität", "correct": true, "because": "Unzureichende Leistung"}, {"text": "Überhitzung", "correct": true, "because": "Schlechte Effizienz"}, {"text": "Komponentenschäden", "correct": true, "because": "Spannungsschwankungen"}, {"text": "Lautes Lüftergeräusch", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein modulares Netzteil?', 4, '[{"text": "Besseres Kabelmanagement", "correct": true, "because": "Nur nötige Kabel"}, {"text": "Einfacher Einbau", "correct": true, "because": "Weniger Kabelgewirr"}, {"text": "Flexibilität", "correct": true, "because": "Anpassbar an Bedarf"}, {"text": "Höhere Wattzahl", "correct": false, "because": "Unabhängig von Modularität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten erfordern oft zusätzliche Stromanschlüsse vom Netzteil?', 3, '[{"text": "Grafikkarten", "correct": true, "because": "Hoher Leistungsbedarf"}, {"text": "Prozessoren", "correct": true, "because": "Zusätzlicher 4/8-Pin"}, {"text": "Festplatten", "correct": true, "because": "SATA-Power nötig"}, {"text": "Tastaturen", "correct": false, "because": "Über USB versorgt"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Netzteil mit 80 PLUS Gold ist effizienter als Bronze. b) Wattzahl ist irrelevant für die Auswahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gold effizienter, Wattzahl wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein ATX-Netzteil passt nur in ATX-Gehäuse. b) Modularität verbessert die Luftzirkulation.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "ATX ja, Modularität hilft"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzteile versorgen Grafikkarten über PCIe-Stecker. b) Ein 400-W-Netzteil reicht für High-End-Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PCIe ja, 400 W zu wenig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Effizienz reduziert Stromkosten. b) Netzteile beeinflussen die Prozessorleistung direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, Leistung indirekt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Netzteil muss die Wattzahl der Komponenten übersteigen. b) Formfaktor ist für die Leistung irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wattzahl ja, Formfaktor für Gehäuse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

